#PBS -S /bin/sh
#PBS -N foggie_bench
#PBS -l select=@NODES@:ncpus=@NCPUS@:model=@MODEL@
#PBS -l walltime=@WALLTIME@
#PBS -q @QUEUE@
#PBS -j oe
#PBS -o @OUT@/pbs_output.log
#PBS -koed
#PBS -V
#PBS -W group_list=@GROUP@

# Generated by make_bench_run.py - modules mirror src/qsub_compile_enzo.sh.
# Adjust module versions here if the production toolchain moves.

module load comp-intel/2020.4.304
module load hdf5/1.8.18_serial

# Runtime environment for the MPICH + grackle the executable links
# (paths match Make.mach.pleiades-mpich and the FOGGIE production setup).
export LD_LIBRARY_PATH="/u/jtumlins/installs/mpich-4.0.3/usr/local/lib":"/u/jtumlins/installs/mpich-4.0.3/usr/lib":"/u/jtumlins/grackle/grackle-3.3.1-dev/build/lib64":$LD_LIBRARY_PATH
export PATH="/nobackup/jtumlins/anaconda3/bin:/u/scicon/tools/bin/:/u/jtumlins/installs/mpich-4.0.3/usr/local/bin:$PATH"

cd @OUT@

# The snapshot directory (shadow copy with the edited parameter file) was
# prepared by make_bench_run.py; restart with the standard Enzo syntax.
# The launcher must belong to the MPI the executable links against
# (MPICH per Make.mach.pleiades-mpich), not the system MPT mpiexec.
@MPIEXEC@ -np @RANKS@ @ENZO@ -d -r @RESTART_REL@ > enzo_bench.log 2>&1
status=$?

echo "exit=$status" > bench_exit_status
exit $status
